head.script:
scwin.checkValue = function(log) {
	if (log) {
		return true;
	}
	return false;
};

scwin.checktype = function() {
	return typeof log;
};

scwin.setVal = function() {
	return scwin.checkValue(log);
};

scwin.checkVal = function() {
	return WebSquare.logger.getLog().indexOf(String(log)) !== -1;
};

// SKT-310: wframe(scope) 의 getObjList 에 tabControl 안 wframe id 포함 여부 - 빠진 id 목록(없으면 ''). 2026-11
scwin.missingTabWframes = function() {
	return ['wfm_tab1', 'wfm_tab2_1', 'wfm_tab2_2', 'wfm_tab4'].filter(function(id) { return log.indexOf(id) === -1; }).join(',');
};
scwin.onpageload = function() {
	WebSquare.logger.printLog(wfm_main.getObjList());
	log = wfm_main.getObjList();
};
